import random
from itertools import combinations

def girth(adj, n):
    best = float('inf')
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        while q:
            nq = []
            for u in q:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nq.append(v)
                    elif parent[u] != v and dist[v] >= dist[u]:
                        c = dist[u]+dist[v]+1
                        if c < best:
                            best = c
            q = nq
    return best

def is_4_colorable(edges, n):
    color = [-1]*n
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(i):
        if i == n: return True
        v = order[i]
        used = set(color[u] for u in adj[v] if color[u]!=-1)
        for c in range(4):
            if c not in used:
                color[v] = c
                if bt(i+1): return True
                color[v] = -1
        return False
    return bt(0)

