from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from itertools import combinations, permutations

n = 15
pairs = list(combinations(range(n),2))
edge_var = {p: i+1 for i,p in enumerate(pairs)}
NE = len(pairs)

def eid(a,b):
    if a>b: a,b=b,a
    return edge_var[(a,b)]

solver = Glucose3()

def gen_cycles(k):
    for subset in combinations(range(n), k):
        first = subset[0]
        rest = subset[1:]
        for perm in permutations(rest):
            cyc = (first,) + perm
            rev = (first,) + perm[::-1]
            if cyc <= rev:
                yield cyc

for k in [3,4,5,6]:
    for cyc in gen_cycles(k):
        clause = [-eid(cyc[i], cyc[(i+1)%k]) for i in range(k)]
        solver.add_clause(clause)

next_var = NE + 1
cnf = CardEnc.atleast(lits=list(range(1, NE+1)), bound=22, top_id=next_var, encoding=EncType.seqcounter)
for cl in cnf.clauses:
    solver.add_clause(cl)

import time
t = time.time()
res = solver.solve()
print("time:", time.time()-t, "result:", res)
if res:
    model = solver.get_model()
    edges = []
    for p,v in edge_var.items():
        if model[v-1] > 0:
            edges.append(p)
    print(len(edges), "edges:", edges)
